    ("04 phone", ["555-201-9988"]),
    ("05 fax", ["555-201-9989"]),
    ("06 email", ["lupe735@example.net"]),
    ("07 ssn", ["999-12-3456"]),
    ("08 mrn", ["MR-77001"]),
    ("09 health plan number", []),  # covered by test_09 below with a claim
    ("10 account numbers", ["ACC-990011"]),
    ("11 licence numbers", ["S11122233", "X55667788X"]),
    ("12 vehicle identifiers", ["2HGFB2F59EH501234"]),
