@pytest.mark.parametrize(("label", "needles"), CASES, ids=[c[0] for c in CASES])
def test_class_is_gone(label, needles, patient, encounter):
    text = blob(patient, encounter)
    for n in needles:
        assert n not in text, (label, n)


def test_09_health_plan_number(scrubber, schemas):
    from carelake.schemas import coerce

    claim = {
        "resourceType": "Claim",
        "id": "cl-1",
        "status": "active",
        "use": "claim",
        "type": {"coding": [{"code": "professional"}]},
        "patient": {"reference": "urn:uuid:" + PID, "display": "Lupe735 Ortiz186"},
        "billablePeriod": {"start": "2021-03-09T08:15:00-06:00"},
        "insurance": [{"coverage": {"display": "Medicaid", "identifier": {"value": "MCD-4455-7788"}}}],
    }
    row = extract.claim_row(claim)
    assert row["member_no"] == "MCD-4455-7788"
    out = scrubber.row(schemas["claims"], {**coerce(schemas["claims"], row), "_cohort": "t"})
    assert "member_no" not in out and "MCD-4455" not in blob(out) and "Lupe735" not in blob(out)
    assert out["payer"] == "Medicaid"


def test_dropped_columns_are_absent_not_null(patient):
    for col in (
        "ssn",
        "surname",
        "forenames",
        "tel",
        "fax",
        "mail",
        "photo",
        "street",
        "town",
        "lat",
        "lng",
        "mrn",
        "license_no",
        "passport_no",
        "narrative",
        "mother_maiden",
        "maiden_surname",
        "born_town",
    ):
        assert col not in patient


def test_dob_reduced_to_offset_year_and_bracket(patient):
    assert (
        patient["birth_year"] in (1970, 1971, 1972)
        and patient["age_bracket"] == "40 to 64"
        and patient["over_89"] is False
    )


def test_dates_offset_consistently_within_a_patient(scrubber, encounter):
    delta = scrubber.offset_days(PID)
    assert delta != 0 and abs(delta) <= OFFSET_DAYS
    assert encounter["began"] == parse_when("2021-03-09T08:15:00-06:00") + timedelta(days=delta)
    assert (encounter["ended"] - encounter["began"]).total_seconds() == 1800


def test_free_text_swept_but_codes_untouched(encounter, scrubber, schemas):
    from carelake.schemas import coerce

    assert "[redacted]" in encounter["kind"]
    row = extract.observation_rows(
        {
            "resourceType": "Observation",
            "id": "o",
            "status": "final",
            "code": {
                "coding": [{"system": "http://loinc.org", "code": "4548-4", "display": "A1c, see http://x.y"}]
            },
            "subject": {"reference": "urn:uuid:" + PID},
            "effectiveDateTime": "2020-01-01T00:00:00Z",
            "valueQuantity": {"value": 6.2, "unit": "%"},
        }
    )[0]
    out = scrubber.row(schemas["observations"], {**coerce(schemas["observations"], row), "_cohort": "t"})
    assert out["system"] == "http://loinc.org" and out["label"] == "A1c, see [redacted]"


def test_digests_join_across_tables_and_depend_on_the_secret(scrubber, patient, encounter):
    assert patient["pid"] == encounter["pid"] == scrubber.digest(PID)
    assert re.fullmatch(r"[0-9a-f]{32}", patient["pid"])
    assert Scrubber("other-secret", AS_OF).digest(PID) != patient["pid"]


def test_offsets_are_spread_and_never_zero():
    s = Scrubber("s", AS_OF)
    seen = {s.offset_days(f"p{i}") for i in range(3000)}
    assert 0 not in seen and min(seen) >= -OFFSET_DAYS and max(seen) <= OFFSET_DAYS and len(seen) > 300


def test_over_89_loses_birth_year(scrubber, schemas):
    from carelake.schemas import coerce

    row = {**extract.patient_row(PATIENT), "dob": "1931-01-01"}
    out = scrubber.row(schemas["patients"], {**coerce(schemas["patients"], row), "_cohort": "t"})
    assert out["age_bracket"] == "90 and over" and out["birth_year"] is None and out["over_89"] is True


@pytest.mark.parametrize(
    ("age", "label"),
    [
        (0, "under 18"),
        (17, "under 18"),
        (18, "18 to 39"),
        (39, "18 to 39"),
        (40, "40 to 64"),
        (64, "40 to 64"),
        (65, "65 to 89"),
        (89, "65 to 89"),
        (90, "90 and over"),
    ],
)
def test_brackets(age, label):
    assert bracket(age) == label


def test_zip3():
    assert (
        zip3("61602") == "616"
        and zip3("61602-1234") == "616"
        and zip3("03644") == "000"
        and zip3("123") is None
    )


def test_empty_secret_refused():
    with pytest.raises(ValueError):
        Scrubber("", AS_OF)
